patch -p0 <<'PATCH'
--- /dev/null
+++ tests/src/unit-enum_serialization.cpp
@@ -0,0 +1,75 @@
+//     __ _____ _____ _____
+//  __|  |   __|     |   | |  JSON for Modern C++ (supporting code)
+// |  |  |__   |  |  | | | |  version 3.11.3
+// |_____|_____|_____|_|___|  https://github.com/nlohmann/json
+//
+// SPDX-FileCopyrightText: 2013-2023 Niels Lohmann <https://nlohmann.me>
+// SPDX-License-Identifier: MIT
+
+#include "doctest_compatibility.h"
+
+#include <nlohmann/json.hpp>
+using nlohmann::json;
+
+#include <cstdint>
+#include <limits>
+
+TEST_CASE_TEMPLATE("enum serialization preserves the underlying integer type", T,
+                   std::int8_t, std::uint8_t, std::int16_t, std::uint16_t,
+                   std::int32_t, std::uint32_t, std::int64_t, std::uint64_t)
+{
+    enum class scoped_enum : T {};
+    enum unscoped_enum : T {};
+
+    for (const T value : {(std::numeric_limits<T>::min)(), T(0), T(1), (std::numeric_limits<T>::max)()})
+    {
+        CAPTURE(value);
+        const json expected = value;
+
+        for (const auto& j : {json(static_cast<scoped_enum>(value)), json(static_cast<unscoped_enum>(value))})
+        {
+            CHECK(j.type() == expected.type());
+            CHECK(j.template get<T>() == value);
+            CHECK(j.dump() == expected.dump());
+            CHECK(j.template get<scoped_enum>() == static_cast<scoped_enum>(value));
+            CHECK(j.template get<unscoped_enum>() == static_cast<unscoped_enum>(value));
+        }
+
+        json assigned = "replace this string";
+        nlohmann::to_json(assigned, static_cast<scoped_enum>(value));
+        CHECK(assigned.type() == expected.type());
+        CHECK(assigned == expected);
+
+        assigned = "replace this string";
+        assigned = static_cast<unscoped_enum>(value);
+        CHECK(assigned.type() == expected.type());
+        CHECK(assigned == expected);
+    }
+}
+
+TEST_CASE("unsigned 64-bit enums serialize without becoming negative")
+{
+    enum class book_id : std::uint64_t
+    {
+        high_bit = std::uint64_t(1) << 63,
+        almost_max = (std::numeric_limits<std::uint64_t>::max)() - 1,
+        max = (std::numeric_limits<std::uint64_t>::max)()
+    };
+
+    const json large_id = book_id::high_bit;
+    CHECK(large_id > 0u);
+    CHECK(to_string(large_id) == "9223372036854775808");
+    CHECK(large_id.is_number_unsigned());
+    CHECK(json::parse(large_id.dump()).get<book_id>() == book_id::high_bit);
+
+    const json almost_max = book_id::almost_max;
+    CHECK(almost_max > 0u);
+    CHECK(almost_max.dump() == "18446744073709551614");
+    CHECK(almost_max.is_number_unsigned());
+    CHECK(json::parse(almost_max.dump()).get<book_id>() == book_id::almost_max);
+
+    const json max = book_id::max;
+    CHECK(max.dump() == "18446744073709551615");
+    CHECK(max.is_number_unsigned());
+    CHECK(json::parse(max.dump()).get<book_id>() == book_id::max);
+}
PATCH
cd /testbed/build && cmake .. >/tmp/json-enum-cmake.log && make -s test-enum_serialization_cpp11 && ./tests/test-enum_serialization_cpp11

patch -p0 <<'PATCH'
--- include/nlohmann/detail/conversions/to_json.hpp
+++ include/nlohmann/detail/conversions/to_json.hpp
@@ -12,7 +12,7 @@
 #include <iterator> // begin, end
 #include <string> // string
 #include <tuple> // tuple, get
-#include <type_traits> // is_same, is_constructible, is_floating_point, is_enum, underlying_type
+#include <type_traits> // is_same, is_constructible, is_floating_point, is_enum, underlying_type, is_unsigned
 #include <utility> // move, forward, declval, pair
 #include <valarray> // valarray
 #include <vector> // vector
@@ -335,7 +335,8 @@
 inline void to_json(BasicJsonType& j, EnumType e) noexcept
 {
     using underlying_type = typename std::underlying_type<EnumType>::type;
-    external_constructor<value_t::number_integer>::construct(j, static_cast<underlying_type>(e));
+    constexpr auto type = std::is_unsigned<underlying_type>::value ? value_t::number_unsigned : value_t::number_integer;
+    external_constructor<type>::construct(j, static_cast<underlying_type>(e));
 }
 #endif  // JSON_DISABLE_ENUM_SERIALIZATION

--- docs/mkdocs/docs/features/enum_conversion.md
+++ docs/mkdocs/docs/features/enum_conversion.md
@@ -1,8 +1,9 @@
 # Specializing enum conversion

-By default, enum values are serialized to JSON as integers. In some cases this could result in undesired behavior. If an
-enum is modified or re-ordered after data has been serialized to JSON, the later de-serialized JSON data may be
-undefined or a different enum value than was originally intended.
+By default, enum values are serialized to JSON as integers, preserving the signedness of the underlying type. Enums with
+unsigned underlying types are stored as unsigned integers. In some cases integer serialization could result in undesired
+behavior. If an enum is modified or re-ordered after data has been serialized to JSON, the later de-serialized JSON data
+may be undefined or a different enum value than was originally intended.

 It is possible to more precisely specify how a given enum is mapped to and from JSON as shown below:

PATCH
python3 tools/amalgamate/amalgamate.py -c tools/amalgamate/config_json.json -s . && git --no-pager diff --stat && git --no-pager diff --check && cd /testbed/build && make -s test-enum_serialization_cpp11 test-conversions_cpp11 test-udt_cpp11 && ./tests/test-enum_serialization_cpp11 && ./tests/test-conversions_cpp11 && ./tests/test-udt_cpp11

